FAMILIES: Final[tuple[str, ...]] = (
    "request",
    "auth",
    "account",
    "input",
    "method",
    "pipe",
    "model",
    "provider",
    "run",
    "security",
    "runtime",
    "client",
)
"""The core families, in the order the registry presents them."""

EXTENSION_PREFIXES: Final[dict[str, str]] = {
    "pipelex": "https://docs.pipelex.com/errors",
}
"""The registered extension prefixes, each with the base URL its codes' pages are published under."""

FAMILY_DOMAINS: Final[dict[str, ProblemDomain]] = {
    "auth": ProblemDomain.ACCOUNT,
    "account": ProblemDomain.ACCOUNT,
    "input": ProblemDomain.INPUT,
}
"""The domain a reader reads for a family whose every code declares that domain; a family whose codes differ reads as `runtime`."""

FAMILY_STEP_KINDS: Final[dict[str, StepKind]] = {}
"""The step kind a reader reads for a family whose every code gives that kind in both its steps, to the actor and to any other reader;
another family reads `report`."""

STATUS_READINGS: Final[dict[int, CoreCode]] = {
    405: CoreCode.REQUEST_METHOD_NOT_ALLOWED,
    503: CoreCode.RUNTIME_UNAVAILABLE,
}
"""The statuses that name one core code a client can state completely, by which an answer that is no problem document is read."""
